/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily } = loadMontserrat("normal", { weights: ["900"] });



export type ComponentNameProps = Record<string, any>;

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#f7f5f0",
  transparentBackground = false,
  durationInSeconds = 6,
  textColor = "#0c151c",
  accentColorRed = "#f32e15",
  accentColorGrey = "#e4e3de",
  text = "marketing",
  fontSize = 180,
  crackIntensity = 1.0,
  shakeStrength = 15,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Helpers
  const getRandom = (seed: string, min: number, max: number) => {
    return min + random(seed) * (max - min);
  };

  // Timeline Events
  // Frame 18: Impact / slam down
  // Frame 50: Sudden crack shockwave
  // Frame 50 - 80: Cracks spread
  // Frame 60 - 180: Shards falling

  // 1. Entrance Spring (Frames 0 - 18)
  const entrySpring = spring({
    frame,
    fps,
    config: { damping: 12, mass: 0.9 },
  });
  const entryScale = interpolate(entrySpring, [0, 1], [1.7, 1.0]);
  const entryY = interpolate(entrySpring, [0, 1], [-250, 0]);
  const entryOpacity = interpolate(frame, [0, 6], [0, 1], { extrapolateRight: "clamp" });

  // 2. Accent Shapes Animations
  const redSpring = spring({
    frame,
    fps,
    config: { damping: 15, mass: 0.8 },
  });
  const redTopY = interpolate(redSpring, [0, 1], [-height * 0.3, 0]);

  const greySpring = spring({
    frame: frame - 6,
    fps,
    config: { damping: 16, mass: 1.0 },
  });
  const greyLeftX = interpolate(greySpring, [0, 1], [-width * 0.15, 0]);

  const smallRedSpring = spring({
    frame: frame - 12,
    fps,
    config: { damping: 14, mass: 0.7 },
  });
  const smallRedRightX = interpolate(smallRedSpring, [0, 1], [width * 0.1, 0]);

  // 3. Shake Mechanics (Impact at 18, Cracking starts at 50)
  let shakeX = 0;
  let shakeY = 0;
  if (frame >= 18 && frame < 32) {
    const intensity = interpolate(frame, [18, 32], [shakeStrength * 0.5, 0]);
    shakeX = (random(`shake-x-1-${frame}`) - 0.5) * intensity;
    shakeY = (random(`shake-y-1-${frame}`) - 0.5) * intensity;
  } else if (frame >= 50 && frame < 85) {
    const intensity = interpolate(frame, [50, 85], [shakeStrength, 0]);
    shakeX = (random(`shake-x-2-${frame}`) - 0.5) * intensity;
    shakeY = (random(`shake-y-2-${frame}`) - 0.5) * intensity;
  }

  // 4. Cracking progression (Frame 50 - 80)
  const crackProgress = interpolate(frame, [50, 85], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 5. Hardcoded custom crack paths per letter to match reference imagery
  const letterCracks: Record<number, string[]> = {
    0: ["M 15 35 L 35 55 L 25 80", "M 75 25 L 65 60 L 85 95"], // m
    1: ["M 20 40 L 45 65 L 30 85", "M 80 55 L 60 70 L 75 95"], // a
    2: ["M 15 25 L 45 55 L 35 95"], // r
    3: [
      "M 10 15 L 45 55 L 25 85 L 55 110",
      "M 80 25 L 48 60 L 68 95",
      "M 45 55 L 85 85",
    ], // k (heavily cracked)
    4: [
      "M 10 50 L 90 50",
      "M 45 15 L 55 55 L 40 95",
      "M 25 80 L 75 80",
    ], // e (heavily cracked)
    5: ["M 25 25 L 55 55 L 35 85 L 65 110"], // t
    6: ["M 50 15 L 50 105"], // i
    7: ["M 15 35 L 50 70 L 30 100", "M 80 45 L 65 85"], // n
    8: [
      "M 25 35 L 60 65 L 35 90 L 80 115",
      "M 85 35 L 60 70 L 75 105",
    ], // g (heavily cracked)
  };

  // 6. Split vectors to separate top/bottom halves dynamically on cracking
  const getLetterSplit = (index: number, progress: number) => {
    const maxShift = 10 * crackIntensity;
    switch (index) {
      case 1: // a
        return { tx: -maxShift * 0.4 * progress, ty: -maxShift * 0.2 * progress, bx: maxShift * 0.4 * progress, by: maxShift * 0.2 * progress };
      case 3: // k
        return { tx: -maxShift * 0.9 * progress, ty: -maxShift * 0.6 * progress, bx: maxShift * 0.9 * progress, by: maxShift * 0.6 * progress };
      case 4: // e
        return { tx: -maxShift * 1.0 * progress, ty: -maxShift * 0.3 * progress, bx: maxShift * 1.0 * progress, by: maxShift * 0.3 * progress };
      case 5: // t
        return { tx: maxShift * 0.3 * progress, ty: -maxShift * 0.5 * progress, bx: -maxShift * 0.3 * progress, by: maxShift * 0.5 * progress };
      case 8: // g
        return { tx: -maxShift * 0.5 * progress, ty: -maxShift * 0.9 * progress, bx: maxShift * 0.5 * progress, by: maxShift * 0.9 * progress };
      default:
        return { tx: 0, ty: 0, bx: 0, by: 0 };
    }
  };

  // 7. Memoized list of physically simulated falling shards/debris
  const shardsList = React.useMemo(() => {
    const list = [];
    const lettersCount = 9;
    for (let i = 0; i < lettersCount; i++) {
      // Heavily cracked letters get more falling debris
      const count = i === 3 || i === 4 || i === 8 ? 8 : 4;
      for (let s = 0; s < count; s++) {
        const seed = `shard-${i}-${s}`;
        const delay = getRandom(seed + "-delay", 0, 35); // Stagger start frames
        const vx = getRandom(seed + "-vx", -5, 5); // horizontal float
        const vy = getRandom(seed + "-vy", -7, -1); // initial pop up
        const rotSpeed = getRandom(seed + "-rot", -12, 12);
        const size = getRandom(seed + "-size", 8, 22);

        // Generate jagged shard shape coordinates
        const p1x = getRandom(seed + "-p1x", 0, 4);
        const p1y = getRandom(seed + "-p1y", 0, 4);
        const p2x = getRandom(seed + "-p2x", 12, 22);
        const p2y = getRandom(seed + "-p2y", -4, 4);
        const p3x = getRandom(seed + "-p3x", 8, 18);
        const p3y = getRandom(seed + "-p3y", 12, 22);
        const p4x = getRandom(seed + "-p4x", -4, 4);
        const p4y = getRandom(seed + "-p4y", 8, 18);

        const path = `M ${p1x} ${p1y} L ${p2x} ${p2y} L ${p3x} ${p3y} L ${p4x} ${p4y} Z`;

        list.push({
          letterIndex: i,
          shardIndex: s,
          delay,
          vx,
          vy,
          rotSpeed,
          size,
          path,
          startX: getRandom(seed + "-sx", 15, 80), // horizontal percent inside the letter width
          startY: getRandom(seed + "-sy", 75, 95), // near base of letter container
        });
      }
    }
    return list;
  }, []);

  const characters = text.split("");

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      {/* Background Vignette for elegant lighting */}
      <AbsoluteFill
        style={{
          background: "radial-gradient(circle, rgba(0,0,0,0) 65%, rgba(0,0,0,0.03) 100%)",
          pointerEvents: "none",
          transition: "none",
        }}
      />

      {/* Accent Shapes Layout Map */}
      {/* 1. Top Left Large Red Square */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: width * 0.18,
          height: height * 0.25,
          backgroundColor: accentColorRed,
          transform: `translateY(${redTopY}px)`,
          transition: "none",
        }}
      />

      {/* 2. Bottom Left Light Grey Square */}
      <div
        style={{
          position: "absolute",
          bottom: 0,
          left: 0,
          width: width * 0.12,
          height: height * 0.14,
          backgroundColor: accentColorGrey,
          transform: `translateX(${greyLeftX}px)`,
          transition: "none",
        }}
      />

      {/* 3. Bottom Right Small Red Block */}
      <div
        style={{
          position: "absolute",
          bottom: height * 0.05,
          right: 0,
          width: width * 0.04,
          height: height * 0.03,
          backgroundColor: accentColorRed,
          transform: `translateX(${smallRedRightX}px)`,
          transition: "none",
        }}
      />

      {/* Centered Main Animation Canvas */}
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          justifyContent: "center",
          alignItems: "baseline",
          transform: `translate(${shakeX}px, ${shakeY + entryY}px) scale(${entryScale})`,
          opacity: entryOpacity,
          width: "100%",
          padding: `0 ${width * 0.05}px`,
          transition: "none",
        }}
      >
        {characters.map((char, index) => {
          const split = getLetterSplit(index, crackProgress);

          return (
            <div
              key={`${char}-${index}`}
              style={{
                position: "relative",
                display: "inline-block",
                fontSize: `${fontSize}px`,
                fontWeight: 900,
                letterSpacing: "-2px",
                lineHeight: 1,
                userSelect: "none",
                margin: "0 2px",
                transition: "none",
              }}
            >
              {/* Top Layer Segment */}
              <div
                style={{
                  position: "relative",
                  display: "inline-block",
                  clipPath: "polygon(0 0, 100% 0, 100% 55%, 0 35%)",
                  transform: `translate(${split.tx}px, ${split.ty}px)`,
                  color: textColor,
                  lineHeight: 1,
                  transition: "none",
                }}
              >
                {char}
              </div>

              {/* Bottom Layer Segment */}
              <div
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  width: "100%",
                  height: "100%",
                  clipPath: "polygon(0 35%, 100% 55%, 100% 100%, 0 100%)",
                  transform: `translate(${split.bx}px, ${split.by}px)`,
                  color: textColor,
                  lineHeight: 1,
                  transition: "none",
                }}
              >
                {char}
              </div>

              {/* Crack Overlay SVG Layer */}
              {letterCracks[index] && (
                <svg
                  style={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                    width: "100%",
                    height: "100%",
                    pointerEvents: "none",
                    overflow: "visible",
                    transition: "none",
                  }}
                  viewBox="0 0 100 120"
                >
                  {letterCracks[index].map((pathData, pIdx) => (
                    <path
                      key={`crack-${index}-${pIdx}`}
                      d={pathData}
                      fill="none"
                      stroke={backgroundColor}
                      strokeWidth={3.5 * crackIntensity}
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeDasharray="150 150"
                      strokeDashoffset={(1 - crackProgress) * 150}
                      style={{ transition: "none" }}
                    />
                  ))}
                </svg>
              )}

              {/* Falling Shards/Debris Overlay Layer */}
              <div
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  width: "100%",
                  height: "100%",
                  pointerEvents: "none",
                  overflow: "visible",
                  transition: "none",
                }}
              >
                {shardsList
                  .filter((s) => s.letterIndex === index)
                  .map((shard) => {
                    const startFrame = 50 + shard.delay;
                    if (frame < startFrame) return null;

                    const t = frame - startFrame;
                    const gravity = 0.45;
                    const x = shard.vx * t;
                    const y = shard.vy * t + 0.5 * gravity * t * t;
                    const rot = shard.rotSpeed * t;
                    const opacity = interpolate(t, [0, 45], [1, 0], { extrapolateRight: "clamp" });
                    const scale = interpolate(t, [0, 45], [1, 0.3], { extrapolateRight: "clamp" });

                    if (opacity <= 0) return null;

                    return (
                      <svg
                        key={`shard-${shard.letterIndex}-${shard.shardIndex}`}
                        style={{
                          position: "absolute",
                          left: `${shard.startX}%`,
                          top: `${shard.startY}%`,
                          width: shard.size * (fontSize / 180),
                          height: shard.size * (fontSize / 180),
                          transform: `translate(${x}px, ${y}px) rotate(${rot}deg) scale(${scale})`,
                          opacity,
                          overflow: "visible",
                          pointerEvents: "none",
                          transition: "none",
                        }}
                        viewBox="0 0 30 30"
                      >
                        <path d={shard.path} fill={textColor} style={{ transition: "none" }} />
                      </svg>
                    );
                  })}
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default ComponentName;